65	
66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final OwnerRequestValidator ownerRequestValidator;
84	
85	    private final PostcodeValidator postcodeValidator;
86	
87	    private final DuplicateOwnerValidator duplicateOwnerValidator;
88	
89	    private final PossibleDuplicateDetector possibleDuplicateDetector;
90	
91	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
92	
93	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
94	
95	    private final RegistrationDateValidator registrationDateValidator;
96	
97	    private final TelephoneNormalizer telephoneNormalizer;
98	
99	    private final EmailNormalizer emailNormalizer;
100	
101	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
102	
103	    private final AddressFormNormalizer addressFormNormalizer;
104	
105	    private final CustomerCodeGenerator customerCodeGenerator;
106	
107	    private final HouseholdIdGenerator householdIdGenerator;
108	
109	    private final HouseholdSizeCalculator householdSizeCalculator;
110	
111	    private final OwnerAuditLogger ownerAuditLogger;
112	
113	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
114	
115	    private final OwnerCreationIdempotencyStore idempotencyStore;
116	
117	    public OwnerRestControllerV1(ClinicService clinicService,
118	                                 OwnerMapper ownerMapper,
119	                                 PetMapper petMapper,
120	                                 VisitMapper visitMapper,
121	                                 OwnerRequestValidator ownerRequestValidator,
122	                                 PostcodeValidator postcodeValidator,
123	                                 DuplicateOwnerValidator duplicateOwnerValidator,
124	                                 PossibleDuplicateDetector possibleDuplicateDetector,
125	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
126	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
127	                                 RegistrationDateValidator registrationDateValidator,
128	                                 TelephoneNormalizer telephoneNormalizer,
129	                                 EmailNormalizer emailNormalizer,
130	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
131	                                 AddressFormNormalizer addressFormNormalizer,
132	                                 CustomerCodeGenerator customerCodeGenerator,
133	                                 HouseholdIdGenerator householdIdGenerator,
134	                                 HouseholdSizeCalculator householdSizeCalculator,
135	                                 OwnerAuditLogger ownerAuditLogger,
136	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
137	                                 OwnerCreationIdempotencyStore idempotencyStore) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	        this.ownerRequestValidator = ownerRequestValidator;
143	        this.postcodeValidator = postcodeValidator;
144	        this.duplicateOwnerValidator = duplicateOwnerValidator;
145	        this.possibleDuplicateDetector = possibleDuplicateDetector;
146	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
147	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
148	        this.registrationDateValidator = registrationDateValidator;
149	        this.telephoneNormalizer = telephoneNormalizer;
150	        this.emailNormalizer = emailNormalizer;
151	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
152	        this.addressFormNormalizer = addressFormNormalizer;
153	        this.customerCodeGenerator = customerCodeGenerator;
154	        this.householdIdGenerator = householdIdGenerator;
155	        this.householdSizeCalculator = householdSizeCalculator;
156	        this.ownerAuditLogger = ownerAuditLogger;
157	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
158	        this.idempotencyStore = idempotencyStore;
159	    }
160	
161	    /**
162	     * Map an owner to its DTO and stamp the current bulk-signup warning onto it, so every
163	     * single-owner response reflects whether more than 80 owners have been created today.
164	     */
165	    private OwnerDto toOwnerDto(Owner owner) {
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
168	        return ownerDto;
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
174	        Collection<Owner> owners;
175	        if (lastName != null) {
176	            owners = this.clinicService.findOwnerByLastName(lastName);
177	        } else {
178	            owners = this.clinicService.findAllOwners();
179	        }
180	        if (owners.isEmpty()) {
181	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	        }
183	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
184	    }
185	
186	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
187	    @Override
188	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
189	        Owner owner = this.clinicService.findOwnerById(ownerId);
190	        if (owner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
199	        if (StringUtils.hasText(idempotencyKey)) {
200	            Optional<Owner> alreadyCreated = this.idempotencyStore.find(idempotencyKey)
201	                .map(this.clinicService::findOwnerById);
202	            if (alreadyCreated.isPresent()) {
203	                return new ResponseEntity<>(toOwnerDto(alreadyCreated.get()), HttpStatus.OK);
204	            }
205	        }
206	        Owner owner = createOwner(ownerFieldsDto);
207	        if (StringUtils.hasText(idempotencyKey)) {
208	            this.idempotencyStore.remember(idempotencyKey, owner.getId());
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        headers.setLocation(UriComponentsBuilder.newInstance()
212	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
213	        return new ResponseEntity<>(toOwnerDto(owner), headers, HttpStatus.CREATED);
214	    }
215	
216	    /**
217	     * Apply every create-time rule to the submitted fields and persist the resulting owner.
218	     */
219	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
220	        this.addressFormNormalizer.normalize(ownerFieldsDto);
221	        this.ownerRequestValidator.validate(ownerFieldsDto);
222	        this.postcodeValidator.validate(ownerFieldsDto);
223	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
224	        this.registrationDateValidator.validate(ownerFieldsDto.getRegistrationDate());
225	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
226	        ownerFieldsDto.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
227	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
228	        this.disposableEmailDomainValidator.validate(ownerFieldsDto.getEmail());
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
231	        // The householdId is deterministic from (lastName, postcode), so every owner carries the
232	        // identifier of its household automatically.
233	        owner.setHouseholdId(
234	            this.householdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
235	        if (sharesHousehold) {
236	            // A declared household member is deliberately allowed and, being declared, is never a
237	            // suspected duplicate.
238	            owner.setPossibleDuplicate(false);
239	            owner.setPossibleDuplicateOf(null);
240	        } else {
241	            this.duplicateOwnerValidator.validate(owner);
242	            Integer possibleDuplicateOf = this.possibleDuplicateDetector.findPossibleDuplicate(owner);
243	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
244	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
245	        }
246	        owner.setCustomerCode(
247	            this.customerCodeGenerator.generate(owner.getPostcode(), owner.getTelephone(),
248	                owner.getLastName()));
249	        owner.setNamesakeCount(
250	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
251	        owner.setHouseholdSize(this.householdSizeCalculator.size(owner));
252	        this.clinicService.saveOwner(owner);
253	        this.ownerAuditLogger.created(owner);
254	        return owner;
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
260	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
261	        if (currentOwner == null) {
262	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	        }
264	        currentOwner.setAddress(ownerFieldsDto.getAddress());
265	        currentOwner.setCity(ownerFieldsDto.getCity());
266	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
267	        currentOwner.setLastName(ownerFieldsDto.getLastName());
268	        currentOwner.setTitle(ownerFieldsDto.getTitle());
269	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
270	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
271	        this.clinicService.saveOwner(currentOwner);
272	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
273	    }
274	
275	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
276	    @Transactional
277	    @Override
278	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
279	        Owner owner = this.clinicService.findOwnerById(ownerId);
280	        if (owner == null) {
281	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
282	        }
283	        this.clinicService.deleteOwner(owner);
284	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
285	    }
286	
287	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
288	    @Override
289	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
290	        Owner owner = this.clinicService.findOwnerById(ownerId);
291	        if (owner == null) {
292	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
293	        }
294	        HttpHeaders headers = new HttpHeaders();
295	        Pet pet = petMapper.toPet(petFieldsDto);
296	        owner.setId(ownerId);
297	        pet.setOwner(owner);
298	        pet.getType().setName(null);
299	        this.clinicService.savePet(pet);
300	        PetDto petDto = petMapper.toPetDto(pet);
301	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
302	            .buildAndExpand(pet.getId()).toUri());
303	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
304	    }
305	
306	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
307	    @Override
308	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
309	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
310	        if (currentOwner != null) {
311	            Pet currentPet = this.clinicService.findPetById(petId);
312	            if (currentPet != null) {
313	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
314	                currentPet.setName(petFieldsDto.getName());
315	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
316	                this.clinicService.savePet(currentPet);
317	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
318	            }
319	        }
320	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	    }
322	
323	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
324	    @Override
325	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
326	        HttpHeaders headers = new HttpHeaders();
327	        Visit visit = visitMapper.toVisit(visitFieldsDto);
328	        Pet pet = new Pet();
329	        pet.setId(petId);
330	        visit.setPet(pet);
331	        this.clinicService.saveVisit(visit);
332	        VisitDto visitDto = visitMapper.toVisitDto(visit);
333	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
334	            .buildAndExpand(visit.getId()).toUri());
335	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
336	    }
337	
338	
339	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
340	    @Override
341	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
342	        Owner owner = this.clinicService.findOwnerById(ownerId);
343	        if (owner != null) {
344	            Pet pet = owner.getPet(petId);
345	            if (pet != null) {
346	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
347	            }
348	        }
349	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
350	    }
351	}
