141	    public String getCity() {
142	        return this.city;
143	    }
144	
145	    public void setCity(String city) {
146	        this.city = city;
147	    }
148	
149	    public String getTelephone() {
150	        return this.telephone;
151	    }
152	
153	    public void setTelephone(String telephone) {
154	        this.telephone = telephone;
155	    }
156	
157	    /**
158	     * The owner's stored E.164 {@link #getTelephone() telephone} formatted for humans: the country
159	     * code, a space, then the national digits grouped in threes (e.g. {@code "+61 412 345 678"}).
160	     * The raw {@link #getTelephone() telephone} stays in E.164 form. Absent until a telephone has
161	     * been set.
162	     */
163	    public String getTelephoneDisplay() {
164	        return Telephone.forDisplay(this.telephone);
165	    }
166	
167	    public String getEmail() {
168	        return this.email;
169	    }
170	
171	    public void setEmail(String email) {
172	        this.email = email;
173	    }
174	
175	    public String getPostcode() {
176	        return this.postcode;
177	    }
178	
179	    public void setPostcode(String postcode) {
180	        this.postcode = postcode;
181	    }
182	
183	    public LocalDate getRegistrationDate() {
184	        return this.registrationDate;
185	    }
186	
187	    public void setRegistrationDate(LocalDate registrationDate) {
188	        this.registrationDate = registrationDate;
189	    }
190	
191	    public LocalDate getBirthDate() {
192	        return this.birthDate;
193	    }
194	
195	    public void setBirthDate(LocalDate birthDate) {
196	        this.birthDate = birthDate;
197	    }
