216	        return this.namesakeCount;
217	    }
218	
219	    public void setNamesakeCount(Integer namesakeCount) {
220	        this.namesakeCount = namesakeCount;
221	    }
222	
223	    public Integer getHouseholdSize() {
224	        return this.householdSize;
225	    }
226	
227	    public void setHouseholdSize(Integer householdSize) {
228	        this.householdSize = householdSize;
229	    }
230	
231	    /**
232	     * Whether this owner, though not a hard duplicate, shares an existing owner's last name and
233	     * postcode while holding a different telephone. Resolved at creation and stored so it is
234	     * reported consistently on every later read.
235	     */
236	    public Boolean getPossibleDuplicate() {
237	        return this.possibleDuplicate;
238	    }
239	
240	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
241	        this.possibleDuplicate = possibleDuplicate;
242	    }
243	
244	    /**
245	     * The id of the existing owner this owner is a possible duplicate of, or {@code null} when it
246	     * is not a possible duplicate.
247	     */
248	    public Integer getPossibleDuplicateOf() {
249	        return this.possibleDuplicateOf;
250	    }
251	
252	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
253	        this.possibleDuplicateOf = possibleDuplicateOf;
254	    }
255	
256	    /**
257	     * Whether this owner has been soft-deleted. A soft-deleted owner keeps its row and remains
258	     * retrievable, but is ignored by the create endpoint's duplicate and identity checks. A newly
259	     * created owner is never deleted.
260	     */
261	    public boolean isDeleted() {
262	        return this.deleted;
263	    }
264	
265	    public void setDeleted(boolean deleted) {
266	        this.deleted = deleted;
267	    }
268	
269	    /**
270	     * The owner's identity key: the single derived value used to detect duplicate owners, formed
271	     * as {@code normalizedTelephone + '|' + email + '|' + householdId} where an absent telephone,
272	     * email or household contributes an empty string. Two owners are duplicates only when their
273	     * whole identity keys are equal, so housemates that share a {@code householdId} but hold
274	     * different telephones have distinct identity keys and are both allowed.
275	     */
276	    public String getIdentityKey() {
277	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
278	    }
279	
280	    private static String orEmpty(String value) {
281	        return value == null ? "" : value;
282	    }
283	
284	    /**
285	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
286	     * last two digits of the {@link #getFiscalYear() fiscal year} of the business-day-adjusted
287	     * registration date (e.g. {@code 'SMI-0007-M27'}). Derived from the owner's own fields;
288	     * absent until both the customer code and registration date have been assigned.
289	     */
290	    public String getMembershipNumber() {
291	        if (this.customerCode == null || this.registrationDate == null) {
292	            return null;
293	        }
294	        return String.format("%s-M%02d", this.customerCode, FiscalYear.endingYear(this.registrationDate) % 100);
295	    }
296	
297	    /**
298	     * The owner's fiscal year, formatted {@code 'FY<YY>'} and derived from the business-day-adjusted
299	     * {@link #getRegistrationDate() registration date}. The fiscal year starts on 1 July; see
300	     * {@link FiscalYear}. Absent until a registration date has been assigned.
301	     */
302	    public String getFiscalYear() {
303	        if (this.registrationDate == null) {
304	            return null;
305	        }
306	        return FiscalYear.label(this.registrationDate);
307	    }
308	
309	    /**
310	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits of the
311	     * {@link #getCustomerCode() customer code}. Absent until the customer code has been assigned.
312	     */
313	    public Integer getCheckDigit() {
314	        if (this.customerCode == null) {
315	            return null;
316	        }
317	        return Luhn.checkDigit(this.customerCode);
318	    }
319	
320	    /**
321	     * The owner's tenure in whole elapsed fiscal years: the number of 1 July boundaries crossed
322	     * from the {@link #getRegistrationDate() registration date} up to today (see {@link FiscalYear}).
323	     * An owner still in their registration fiscal year has a tenure of zero. Absent until a
324	     * registration date is present.
325	     */
326	    public Long getTenureFiscalYears() {
327	        if (this.registrationDate == null) {
328	            return null;
329	        }
330	        return FiscalYear.elapsed(this.registrationDate, LocalDate.now());
331	    }
332	
333	    /**
334	     * The owner's membership points, a score derived from the owner's own fields: starting from 0,
335	     * the owner earns 2 points when an email address is present, 1 point when this owner has no
336	     * namesakes ({@code namesakeCount} is 0), 2 points for a household of 3 or more members, and 3
337	     * points once the owner's {@link #getTenureFiscalYears() tenure} spans at least one full fiscal
338	     * year (the registration and current dates fall in different fiscal years).
339	     */
340	    public Integer getMembershipPoints() {
341	        int points = 0;
342	        boolean hasEmail = this.email != null && !this.email.isEmpty();
343	        if (hasEmail) {
344	            points += 2;
345	        }
346	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
347	        if (unique) {
348	            points += 1;
349	        }
350	        boolean sharedHousehold = this.householdSize != null && this.householdSize >= 3;
351	        if (sharedHousehold) {
352	            points += 2;
353	        }
354	        Long tenureFiscalYears = getTenureFiscalYears();
355	        boolean tenured = tenureFiscalYears != null && tenureFiscalYears >= 1;
356	        if (tenured) {
357	            points += 3;
358	        }
359	        return points;
360	    }
361	
362	    /**
363	     * The owner's membership level, a number from 1 to 4 derived from the owner's
364	     * {@link #getMembershipPoints() membership points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and
365	     * 4 for 6 or more.
366	     */
367	    public Integer getMembershipLevel() {
368	        int points = getMembershipPoints();
369	        if (points >= 6) {
370	            return 4;
371	        }
372	        if (points >= 4) {
373	            return 3;
374	        }
375	        if (points >= 2) {
376	            return 2;
377	        }
378	        return 1;
379	    }
380	
381	    /**
382	     * The owner's locality: the REGION segment of the {@link #getCustomerCode() customer code} (the
383	     * region derived from the postcode when the identity was assigned), or {@link Regions#UNKNOWN}
384	     * before a customer code has been assigned.
385	     */
386	    public String getLocality() {
387	        if (this.customerCode == null) {
388	            return Regions.UNKNOWN;
389	        }
